def card(task, wd):
    cases = {(3200, 5600): (-133.9, 'Full CTB'), (5600, 3200): (133.9, 'Full CTO'), (5600, 4300): (54.0, '1/4 CTO'), (5600, 6500): (-24.7, '1/4 CTB')}
    got = {'%d->%d' % k: mired(*k) for k in cases}
    ok = all((abs(got['%d->%d' % k][0] - v[0]) < 0.15 and got['%d->%d' % k][1] == v[1] for k, v in cases.items()))
    rev = mired(5600, 3200)
    return ([check('mired shifts and nearest gels', ok, got, {'%d->%d' % k: v for k, v in cases.items()}), check("3200 -> 5600 reads 'cooler (blue)'", got['3200->5600'][2] == 'cooler (blue)', got['3200->5600'][2], 'cooler (blue)'), check('negative control: the reverse move is not a CTB', not rev[1] == 'Full CTB', rev[1], 'Full CTO')], [jdump(wd / 'mired.json', got)])

def card(task, wd):
    picks = {n: pick_row(r) for n, r in LIB43.items()}
    same_row = all((set(p.values()) <= set(LIB43[n]) for n, p in picks.items()))
    fg_ok = {n: round(contrast(p['fg'], p['bg']), 2) for n, p in picks.items()}
    best = {n: round(max((contrast(a, b) for a in r for b in r if a != b)), 2) for n, r in LIB43.items()}
    g = np.linspace(0, 1, 200)[None, :, None]
    grad = np.repeat(np.array(hx('#FFFFFF')) * (1 - g) + np.array(hx('#9B9B9B')) * g, 20, 0)
    save(grad, wd / 'heading_gradient.png')
    gr = load(wd / 'heading_gradient.png')
    timing = {'entrance': 0.65, 'gap': 0.3, 'crossfade': 0.4, 'hold': 1.5}
    t_ok = 0.5 <= timing['entrance'] <= 0.8 and 0.2 <= timing['gap'] <= 0.4 and (0.3 <= timing['crossfade'] <= 0.5) and (1 <= timing['hold'] <= 2)
    mixed = {'bg': LIB43['pastel_soft'][0], 'fg': LIB43['monochrome'][4], 'accent': LIB43['neon_electric'][0]}
    is_one_row = lambda p: any((set(p.values()) <= set(r) for r in LIB43.values()))
    return ([check('one bg / fg / accent declared per library, all from ONE row', same_row, picks, 'same row'), check("fg/bg is the row's best-contrast pair (body text where the row allows)", fg_ok == best, fg_ok, best), check('>= 4.5 for every row that has such a pair', all((fg_ok[n] >= 4.5 for n in best if best[n] >= 4.5)), [n for n in best if best[n] < 4.5], 'rows without a 4.5 pair are flagged'), check('heading gradient endpoints #FFFFFF -> #9B9B9B', tohex(gr[5, 0]) == '#ffffff' and tohex(gr[5, -1]) == '#9b9b9b', [tohex(gr[5, 0]), tohex(gr[5, -1])], ['#ffffff', '#9b9b9b']), check('demo-kit timing inside its ranges', t_ok, timing, 'entr .5-.8, gap .2-.4, xfade .3-.5, hold 1-2'), check('negative control: a mixed-row pick is rejected', not is_one_row(mixed), mixed, 'rejected')], [wd / 'heading_gradient.png', jdump(wd / 'picks.json', picks)])

def card(task, wd):
    im = Image.new('RGB', (4 * 48, 48), '#ffffff')
    d = ImageDraw.Draw(im)
    for i, (soft, strong) in enumerate(CHIPS.values()):
        d.rounded_rectangle((i * 48 + 6, 6, i * 48 + 42, 42), radius=8, fill=soft)
        d.ellipse((i * 48 + 15, 15, i * 48 + 33, 33), fill=strong)
    im.save(wd / 'chips.png')
    a = np.asarray(im).astype(float)
    chips_ratio = {k: round(contrast(s, b), 2) for k, (b, s) in CHIPS.items()}
    ladder = {k: {st: hsl2hex(h, s, l) for st, l in STOP_L.items()} for k, (h, s) in LADDER_HSL.items()}
    r700 = {k: round(contrast(v[700], v[50]), 2) for k, v in ladder.items()}
    r500 = {k: round(contrast(v[500], v[50]), 2) for k, v in ladder.items()}
    tile_ok = tohex(a[8, 24]) == CHIPS['violet'][0] and tohex(a[24, 24]) == CHIPS['violet'][1]
    soft_txt = {k: round(contrast(b, '#ffffff'), 2) for k, (b, _) in CHIPS.items()}
    return ([check('chip strong-on-soft passes the 3:1 icon/UI tier', all((v >= 3 for v in chips_ratio.values())), chips_ratio, '>= 3'), check('ladder 50 + 700 passes AA body', all((v >= 4.5 for v in r700.values())), r700, '>= 4.5'), check('ladder 50 + 500 reaches the 3:1 large-text tier', all((v >= 3 for v in r500.values())), r500, '>= 3'), check('36 px tile with 18 px icon painted in the tokens', tile_ok, [tohex(a[8, 24]), tohex(a[24, 24])], CHIPS['violet']), check('negative control: the soft tint alone is not readable text on white', not any((v >= 3 for v in soft_txt.values())), soft_txt, '< 3')], [wd / 'chips.png', jdump(wd / 'ladder.json', ladder)])

def card(task, wd):
    bg, text = (hsl2hex(220, 0.1, 0.08), hsl2hex(0, 0, 0.9))
    brand_l, brand_d = (hsl2hex(220, 0.9, 0.5), hsl2hex(220, 0.7, 0.6))
    tiers = {p: tohex(flatten(hx(text), hx(bg), p / 100)) for p in (100, 60, 40)}
    r = {'text': contrast(text, bg), 'brand_dark': contrast(brand_d, bg), 'brand_light_on_dark': contrast(brand_l, bg), 'tier60': contrast(tiers[60], bg), 'brand_on_white': contrast(brand_l, '#ffffff')}
    save(np.hstack([np.full((24, 24, 3), np.array(hx(c), float)) for c in (bg, text, brand_d, tiers[60])]), wd / 'dark.png')
    dh, ds, dl = hex2hsl(brand_d)
    inverted = tohex(255 - np.array(hx('#ffffff'), float))
    return ([check('brand hsl(220 90% 50%) -> hsl(220 70% 60%) (sat -20, L +10)', abs(ds - 0.7) < 0.01 and abs(dl - 0.6) < 0.01, [ds, dl], [0.7, 0.6]), check('text and lifted brand pass 4.5 on the tinted ground', r['text'] >= 4.5 and r['brand_dark'] >= 4.5, r, '>= 4.5'), check('lifted brand reads better than the light-mode brand on dark', r['brand_dark'] > r['brand_light_on_dark'], r, 'dark > light'), check('ground is brand-tinted near-black, never #000 / text never #fff', bg != '#000000' and text != '#ffffff' and (hue_dist(hex2hsl(bg)[0], 220) < 12), [bg, text], 'tinted'), check('negative control: naive inversion gives pure #000', not inverted != '#000000', inverted, '#000000')], [wd / 'dark.png', jdump(wd / 'dark.json', {'bg': bg, 'text': text, 'brand': brand_d, 'tiers': tiers, 'ratios': r})])
